def lookup_domain(request):
    import subprocess
    from django.http import HttpResponse
    domain = request.GET.get("domain", "example.com")
    output = subprocess.check_output(["nslookup", domain], text=True)
    return HttpResponse(output)

def search_log(request):
    import subprocess
    from django.http import HttpResponse
    pattern = request.GET.get("q", "")
    output = subprocess.check_output(["grep", "-n", "--", pattern, "/var/log/app.log"], text=True)
    return HttpResponse(output)

def fetch_url(request):
    import subprocess
    from django.http import HttpResponse
    url = request.GET.get("url", "https://example.com")
    output = subprocess.check_output(["curl", "-s", "--", url], text=True)
    return HttpResponse(output)

def extract_text(request):
    import subprocess
    from django.http import HttpResponse
    document = request.GET["document"]
    text = subprocess.check_output(["pdftotext", document, "-"], text=True)
    return HttpResponse(text)

def whois_lookup(request):
    import subprocess
    from django.http import HttpResponse
    domain = request.GET.get("domain", "example.com")
    output = subprocess.check_output(["whois", "--", domain], text=True)
    return HttpResponse(output)
